//
// "Nothing beats it" rather than "nothing is strictly nearer" is the whole
// point of routing through isNearerOwner. A long-lived agent process can own
// several sessions at the SAME depth — an older stale one and a newer resumed
// one — and at equal depth the rule is recency, not "either will do". An
// earlier version of the adopt check compared only `depth < selected` and so
// accepted a stale sibling of the caller's own session silently, disagreeing
// with the resolver about a case the resolver had already decided.
//
// Fails closed on every uncertainty: no owner recorded, an owner that cannot
// be placed in the ancestry, or a platform that cannot introspect processes.
func CallerOwnerIsNearest(candidate *SessionState, states []*SessionState) bool {
	if candidate == nil || candidate.Owner == nil {
		return false
	}
	ancestry, ok := proclive.CurrentAncestry()
	if !ok {
		return false
	}
	selected := ancestry.Depth(*candidate.Owner)
	if selected < 0 {
		return false
	}
	for _, state := range states {
		if state == nil || state.SessionID == candidate.SessionID || state.Owner == nil {
			continue
		}
		if state.Kind.IsImported() || state.AdoptedIntoWorktreePath != "" {
			continue
		}
		depth := ancestry.Depth(*state.Owner)
		if depth < 0 {
			continue
		}
		if isNearerOwner(depth, selected, state, candidate) {
			return false
		}
	}
	return true
}

