// the resolver found no target state whose owner is in our ancestry, since one
// would have resolved as ResolutionAncestry and been answered above.
//
// Fails closed when the source store cannot be listed.
func sourceOwnerIsNearest(ctx context.Context, sourceStore *session.StateStore, source *session.State) bool {
	states, err := sourceStore.List(ctx)
	if err != nil {
		return false
	}
	return strategy.CallerOwnerIsNearest(source, states)
}

